export const CreateAssistantTaskRequestBody = zod.object({
  "request": zod.string().min(createAssistantTaskRequestBodyRequestMin).max(createAssistantTaskRequestBodyRequestMax),
  "whatNeedsDoing": zod.string().min(createAssistantTaskRequestBodyWhatNeedsDoingMin).max(createAssistantTaskRequestBodyWhatNeedsDoingMax).optional(),
  "forWhom": zod.string().min(1).max(createAssistantTaskRequestBodyForWhomMax).optional(),
  "priority": zod.enum(['Urgent', 'High', 'Medium', 'Low']).optional(),
  "dueDateTime": zod.string().min(1).max(createAssistantTaskRequestBodyDueDateTimeMax).optional(),
  "location": zod.string().max(createAssistantTaskRequestBodyLocationMax).optional(),
  "duration": zod.string().max(createAssistantTaskRequestBodyDurationMax).optional(),
  "recurrence": zod.enum(['none', 'weekly', 'biweekly', 'every4weeks', 'monthly', 'quarterly', 'yearly']).optional(),
  "notes": zod.string().max(createAssistantTaskRequestBodyNotesMax).optional(),
  "photoDataUrl": zod.string().max(createAssistantTaskRequestBodyPhotoDataUrlMax).optional().describe('Optional image context. Used for drafting only and never persisted.'),
  "claudeProjectContext": zod.string().max(createAssistantTaskRequestBodyClaudeProjectContextMax).optional(),
  "requestId": zod.string().min(createAssistantTaskRequestBodyRequestIdMin).max(createAssistantTaskRequestBodyRequestIdMax)
})

export const createAssistantTaskRequestResponseProposalTasksItemConfidenceMin = 0;
export const createAssistantTaskRequestResponseProposalTasksItemConfidenceMax = 100;



export const CreateAssistantTaskRequestResponse = zod.object({
  "proposal": zod.object({
  "id": zod.number(),
  "title": zod.string(),
  "summary": zod.string(),
  "status": zod.enum(['pending', 'approved', 'rejected', 'partial']),
  "sources": zod.array(zod.object({
  "sourceType": zod.enum(['gmail', 'calendar', 'claude_request']),
  "sourceId": zod.string(),
  "title": zod.string(),
  "sourceUrl": zod.string(),
  "recurringId": zod.string().optional(),
  "mailbox": zod.string(),
  "originLabel": zod.string(),
  "calendarId": zod.string().optional(),
  "calendarName": zod.string().optional(),
  "originalSender": zod.string().optional(),
  "forwardedBy": zod.string().optional()
})),
  "tasks": zod.array(zod.object({
  "id": zod.number(),
  "title": zod.string(),
  "rationale": zod.string(),
  "dueDate": zod.coerce.date().nullable(),
  "urgency": zod.enum(['Urgent', 'High', 'Medium', 'Low']),
  "groupName": zod.string(),
  "proposedCategory": zod.string().nullable(),
  "notes": zod.string(),
  "sourceLink": zod.string(),
  "sourceType": zod.string(),
  "sourceId": zod.string(),
  "confidence": zod.number().min(createAssistantTaskRequestResponseProposalTasksItemConfidenceMin).max(createAssistantTaskRequestResponseProposalTasksItemConfidenceMax),
  "assumptions": zod.array(zod.string()),
  "status": zod.enum(['pending', 'approved', 'rejected', 'auto_approved']),
  "approvedTaskId": zod.string().nullish(),
  "matchedRuleId": zod.number().nullish()
})),
  "createdAt": zod.coerce.date(),
  "updatedAt": zod.coerce.date(),
  "requesterId": zod.string().nullish(),
  "requesterName": zod.string()
}),
  "duplicate": zod.boolean(),
  "status": zod.enum(['pending_approval'])
})


/**
 * @summary Create an owner-bound Claude custom connector configuration
 */
export const CreateAssistantConnectorResponse = zod.object({
  "endpoint": zod.string(),
  "authorizationUrl": zod.string(),
  "instructions": zod.string()
})


/**
 * @summary Remote MCP endpoint for the Claude custom connector
 */
export const AssistantMcpResponse = zod.unknown()


